package com.global.ct.frameinventory.frame;

import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.List;

@Service
@RequiredArgsConstructor
public class FrameService {

    private final FrameRepository frameRepository;

    public List<Frame> findAll() {
        return frameRepository.findAll();
    }

    public Frame findByFrameId(String frameId) {
        return frameRepository.findByFrameId(frameId)
                .orElseThrow(() -> new FrameNotFoundException(frameId));
    }

    public Frame create(FrameRequest request) {
        Frame frame = new Frame();
        frame.setFrameId(request.getFrameId());
        frame.setType(request.getType());
        frame.setFormat(request.getFormat());
        frame.setEnvironment(request.getEnvironment());
        frame.setStatus(request.getStatus());
        frame.setCreatedDate(Instant.now());
        frame.setModifiedDate(Instant.now());
        return frameRepository.save(frame);
    }

    public Frame update(String frameId, FrameRequest request) {
        Frame frame = findByFrameId(frameId);
        frame.setType(request.getType());
        frame.setFormat(request.getFormat());
        frame.setEnvironment(request.getEnvironment());
        frame.setStatus(request.getStatus());
        frame.setModifiedDate(Instant.now());
        return frameRepository.save(frame);
    }

    public void delete(String frameId) {
        Frame frame = findByFrameId(frameId);
        frameRepository.delete(frame);
    }
}

package com.global.ct.frameinventory.frame;

import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/frames")
@RequiredArgsConstructor
public class FrameController {

    private final FrameService frameService;

    @GetMapping
    public List<Frame> list() {
        return frameService.findAll();
    }

    @GetMapping("/{frameId}")
    public Frame get(@PathVariable String frameId) {
        return frameService.findByFrameId(frameId);
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public Frame create(@Valid @RequestBody FrameRequest request) {
        return frameService.create(request);
    }

    @PutMapping("/{frameId}")
    public Frame update(@PathVariable String frameId, @Valid @RequestBody FrameRequest request) {
        return frameService.update(frameId, request);
    }

    @DeleteMapping("/{frameId}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void delete(@PathVariable String frameId) {
        frameService.delete(frameId);
    }
}

package com.global.ct.frameinventory.config;

import com.global.ct.frameinventory.frame.FrameNotFoundException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.time.Instant;
import java.util.HashMap;
import java.util.Map;

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(FrameNotFoundException.class)
    public ResponseEntity<Map<String, Object>> handleFrameNotFound(FrameNotFoundException ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now());
        body.put("status", HttpStatus.NOT_FOUND.value());
        body.put("error", "Not Found");
        body.put("message", ex.getMessage());
        return ResponseEntity.status(HttpStatus.NOT_FOUND).body(body);
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<Map<String, Object>> handleValidationErrors(MethodArgumentNotValidException ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now());
        body.put("status", HttpStatus.BAD_REQUEST.value());
        body.put("error", "Bad Request");

        Map<String, String> fieldErrors = new HashMap<>();
        ex.getBindingResult().getFieldErrors().forEach(error ->
                fieldErrors.put(error.getField(), error.getDefaultMessage())
        );
        body.put("fieldErrors", fieldErrors);

        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(body);
    }
}

