package com.global.ct.frameinventory.frame;

import com.global.ct.frameinventory.csv.CsvRowError;
import com.global.ct.frameinventory.csv.CsvUploadResult;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;

@Service
@Slf4j
@RequiredArgsConstructor
public class FrameService {

    private final FrameRepository frameRepository;

    public List<Frame> findAll() {
        return frameRepository.findAll();
    }

    public Frame findByFrameId(String frameId) {
        return frameRepository.findByFrameId(frameId)
                .orElseThrow(() -> new FrameNotFoundException(frameId));
    }

    public Frame create(FrameRequest request) {
        log.info("Creating frame with frameId= {}", request.getFrameId());
        Frame frame = new Frame();
        frame.setFrameId(request.getFrameId());
        frame.setType(request.getType());
        frame.setFormat(request.getFormat());
        frame.setEnvironment(request.getEnvironment());
        frame.setStatus(request.getStatus());
        frame.setCreatedDate(Instant.now());
        frame.setModifiedDate(Instant.now());
        return frameRepository.save(frame);
    }

    public Frame update(String frameId, FrameRequest request) {
        log.info("Updating frame with frameId= {}", frameId);
        Frame frame = findByFrameId(frameId);
        frame.setType(request.getType());
        frame.setFormat(request.getFormat());
        frame.setEnvironment(request.getEnvironment());
        frame.setStatus(request.getStatus());
        frame.setModifiedDate(Instant.now());
        return frameRepository.save(frame);
    }

    public void delete(String frameId) {
        log.info("Deleting frame with frameId= {}", frameId);
        Frame frame = findByFrameId(frameId);
        frameRepository.delete(frame);
    }

    public CsvUploadResult bulkCreate(List<Frame> frames, List<CsvRowError> parseErrors, int totalRows) {
        log.info("Bulk creating {} frames", frames.size());

        List<CsvRowError> allErrors = new ArrayList<>(parseErrors);
        int insertedCount = 0;
        int skippedCount = 0;

        for (Frame frame : frames) {
            if (frameRepository.findByFrameId(frame.getFrameId()).isPresent()) {
                skippedCount++;
                log.debug("Skipping duplicate frameId: {}", frame.getFrameId());
            } else {
                try {
                    if (frame.getCreatedDate() == null) {
                        frame.setCreatedDate(Instant.now());
                    }
                    if (frame.getModifiedDate() == null) {
                        frame.setModifiedDate(Instant.now());
                    }
                    frameRepository.save(frame);
                    insertedCount++;
                } catch (Exception e) {
                    log.error("Failed to save frame: {}", frame.getFrameId(), e);
                    allErrors.add(new CsvRowError(0, frame.getFrameId(), "Failed to save: " + e.getMessage()));
                }
            }
        }

        log.info("Bulk create complete: inserted={}, skipped={}, errors={}", insertedCount, skippedCount, allErrors.size());

        return CsvUploadResult.builder()
                .totalRows(totalRows)
                .insertedCount(insertedCount)
                .skippedCount(skippedCount)
                .errorCount(allErrors.size())
                .errors(allErrors)
                .build();
    }
}

